"use client";

import * as React from "react";
import { CHART_COLORS, SEMANTIC } from "@/lib/chart-colors";
import { formatCompact } from "@/lib/utils";
import { ChartEmpty, ScreenReaderTable } from "./chart-frame";

export type ProjectTime = number | string;

export type ProjectTask = {
  id: string;
  name: string;
  start: ProjectTime;
  end: ProjectTime;
  lane?: number;
  group?: string;
  progress?: number;
  dependencies?: string[];
  critical?: boolean;
  milestone?: boolean;
  status?: "planned" | "active" | "complete" | "blocked";
};

export type TimelineEvent = {
  id: string;
  date: ProjectTime;
  label: string;
  description?: string;
  category?: string;
  status?: ProjectTask["status"];
};

export type ProjectChartProps = {
  data: ProjectTask[];
  ariaLabel?: string;
  onTaskSelect?: (task: ProjectTask) => void;
};

const WIDTH = 760;
const HEIGHT = 350;

function timeValue(value: ProjectTime): number | null {
  if (typeof value === "number") return Number.isFinite(value) ? value : null;
  const dateOnly = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (dateOnly) {
    const result = Date.UTC(Number(dateOnly[1]), Number(dateOnly[2]) - 1, Number(dateOnly[3]));
    return Number.isFinite(result) ? result : null;
  }
  const result = Date.parse(value);
  return Number.isFinite(result) ? result : null;
}

function validTasks(data: ProjectTask[]) {
  return data.flatMap((task) => {
    const start = timeValue(task.start);
    const end = timeValue(task.end);
    if (start == null || end == null || end < start) return [];
    return [{ task, start, end }];
  });
}

function taskStatusColor(task: ProjectTask, index: number) {
  if (task.status === "complete") return SEMANTIC.positive;
  if (task.status === "blocked") return SEMANTIC.negative;
  if (task.status === "active") return SEMANTIC.warning;
  return CHART_COLORS[index % CHART_COLORS.length];
}

function ProjectBars({
  data,
  showDependencies,
  showProgress,
  compact,
  ariaLabel,
  onTaskSelect,
}: ProjectChartProps & {
  showDependencies: boolean;
  showProgress: boolean;
  compact?: boolean;
}) {
  const uid = React.useId().replace(/[^a-zA-Z0-9]/g, "");
  const rows = validTasks(data);
  if (!rows.length) return <ChartEmpty label="No valid project tasks" />;

  const min = Math.min(...rows.map((row) => row.start));
  const max = Math.max(...rows.map((row) => row.end));
  const span = Math.max(max - min, 1);
  const left = compact ? 120 : 154;
  const right = 24;
  const top = 30;
  const bottom = 34;
  const rowHeight = Math.min(compact ? 38 : 46, (HEIGHT - top - bottom) / rows.length);
  const plotWidth = WIDTH - left - right;
  const x = (value: number) => left + ((value - min) / span) * plotWidth;
  const y = (index: number) => top + index * rowHeight + rowHeight / 2;
  const rowById = new Map(rows.map((row, index) => [row.task.id, { ...row, index }]));
  const label = ariaLabel ?? `Gantt chart with ${rows.length} tasks`;

  return (
    <div className="h-full w-full overflow-x-auto" tabIndex={0} aria-label="Scrollable project schedule">
      <svg viewBox={`0 0 ${WIDTH} ${HEIGHT}`} className="h-full min-w-[40rem] w-full" role="group" aria-label={label}>
        <title>{label}</title>
        <desc>Task bars encode start, end, progress, status, and optional dependencies.</desc>
        <defs>
          <marker id={`gantt-arrow-${uid}`} viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse">
            <path d="M 0 0 L 10 5 L 0 10 z" fill="var(--muted-foreground)" />
          </marker>
        </defs>
        {Array.from({ length: 5 }, (_, index) => {
          const value = min + (span * index) / 4;
          return (
            <g key={index}>
              <line x1={x(value)} x2={x(value)} y1={top - 8} y2={HEIGHT - bottom + 6} stroke="var(--chart-grid)" />
              <text x={x(value)} y={HEIGHT - 10} textAnchor="middle" fill="var(--muted-foreground)" fontSize="11">{formatCompact(value)}</text>
            </g>
          );
        })}
        {showDependencies ? rows.flatMap((row) =>
          (row.task.dependencies ?? []).flatMap((dependencyId) => {
            const source = rowById.get(dependencyId);
            const target = rowById.get(row.task.id);
            if (!source || !target) return [];
            const startX = x(source.end);
            const startY = y(source.index);
            const targetX = x(target.start);
            const targetY = y(target.index);
            const elbowX = Math.max(startX + 12, targetX - 12);
            return [
              <path
                key={`${dependencyId}-${row.task.id}`}
                d={`M ${startX} ${startY} H ${elbowX} V ${targetY} H ${targetX - 3}`}
                fill="none"
                stroke="var(--muted-foreground)"
                strokeWidth="1.25"
                markerEnd={`url(#gantt-arrow-${uid})`}
              />,
            ];
          }),
        ) : null}
        {rows.map((row, index) => {
          const centerY = y(index);
          const barHeight = compact ? 16 : 22;
          const startX = x(row.start);
          const endX = x(row.end);
          const width = Math.max(4, endX - startX);
          const color = taskStatusColor(row.task, index);
          const progress = Math.max(0, Math.min(1, row.task.progress ?? 0));
          return (
            <g
              key={row.task.id}
              tabIndex={0}
              role={onTaskSelect ? "button" : "group"}
              aria-label={`${row.task.name}, start ${String(row.task.start)}, end ${String(row.task.end)}, ${Math.round(progress * 100)} percent complete`}
              onClick={() => onTaskSelect?.(row.task)}
              onKeyDown={(event) => {
                if (onTaskSelect && (event.key === "Enter" || event.key === " ")) {
                  event.preventDefault();
                  onTaskSelect(row.task);
                }
              }}
              className="ce-svg-mark cursor-default focus:outline-none"
            >
              <text x={left - 10} y={centerY + 4} textAnchor="end" fill="var(--foreground)" fontSize="11" fontWeight="500">
                {row.task.name.length > 20 ? `${row.task.name.slice(0, 19)}…` : row.task.name}
                <title>{row.task.name}</title>
              </text>
              {row.task.milestone || row.start === row.end ? (
                <rect x={startX - 7} y={centerY - 7} width="14" height="14" transform={`rotate(45 ${startX} ${centerY})`} fill={color} />
              ) : (
                <>
                  <rect x={startX} y={centerY - barHeight / 2} width={width} height={barHeight} rx="5" fill={color} fillOpacity="0.28" stroke={color} strokeWidth={row.task.critical ? 2.5 : 1.25} />
                  {showProgress && progress > 0 ? (
                    <rect x={startX} y={centerY - barHeight / 2} width={width * progress} height={barHeight} rx="5" fill={color} fillOpacity="0.85" />
                  ) : null}
                </>
              )}
              <title>{`${row.task.name}: ${String(row.task.start)} to ${String(row.task.end)}`}</title>
            </g>
          );
        })}
      </svg>
      <ScreenReaderTable><caption>{label} data</caption><thead><tr><th scope="col">Task</th><th scope="col">Start</th><th scope="col">End</th><th scope="col">Progress</th><th scope="col">Status</th></tr></thead><tbody>{rows.map(({ task }) => <tr key={task.id}><th scope="row">{task.name}</th><td>{String(task.start)}</td><td>{String(task.end)}</td><td>{Math.round(Math.max(0, Math.min(1, task.progress ?? 0)) * 100)}%</td><td>{task.status ?? "Unspecified"}</td></tr>)}</tbody></ScreenReaderTable>
    </div>
  );
}

export function GanttChart(props: ProjectChartProps) {
  return <ProjectBars {...props} showDependencies={false} showProgress />;
}

export function AdvancedGanttChart(props: ProjectChartProps) {
  return <ProjectBars {...props} showDependencies showProgress />;
}

export function GanttRangeChart(props: ProjectChartProps) {
  return <ProjectBars {...props} showDependencies={false} showProgress={false} compact />;
}

export type TimelineChartProps = {
  events: TimelineEvent[];
  ariaLabel?: string;
  onEventSelect?: (event: TimelineEvent) => void;
};

function validEvents(events: TimelineEvent[]) {
  return events.flatMap((event) => {
    const date = timeValue(event.date);
    return date == null ? [] : [{ event, date }];
  }).sort((a, b) => a.date - b.date);
}

export function TimelineChart({ events, ariaLabel = "Project timeline", onEventSelect }: TimelineChartProps) {
  const points = validEvents(events);
  if (!points.length) return <ChartEmpty label="No valid timeline events" />;
  const min = points[0].date;
  const max = points[points.length - 1].date;
  const span = Math.max(max - min, 1);
  const x = (value: number) => 50 + ((value - min) / span) * (WIDTH - 100);
  const baseline = HEIGHT / 2;
  return (
    <div className="h-full w-full overflow-x-auto" tabIndex={0} aria-label="Scrollable timeline">
      <svg viewBox={`0 0 ${WIDTH} ${HEIGHT}`} className="h-full min-w-[40rem] w-full" role="group" aria-label={ariaLabel}>
        <title>{ariaLabel}</title>
        <line x1="50" x2={WIDTH - 50} y1={baseline} y2={baseline} stroke="var(--chart-axis)" strokeWidth="2" />
        {points.map(({ event, date }, index) => {
          const above = index % 2 === 0;
          const pointX = x(date);
          const labelY = baseline + (above ? -72 : 76);
          const color = CHART_COLORS[index % CHART_COLORS.length];
          return (
            <g key={event.id} tabIndex={0} role={onEventSelect ? "button" : "group"} aria-label={`${event.label}, ${String(event.date)}${event.description ? `, ${event.description}` : ""}`} onClick={() => onEventSelect?.(event)} onKeyDown={(keyboardEvent) => {
              if (onEventSelect && (keyboardEvent.key === "Enter" || keyboardEvent.key === " ")) {
                keyboardEvent.preventDefault();
                onEventSelect(event);
              }
            }} className="ce-svg-mark">
              <line x1={pointX} x2={pointX} y1={baseline} y2={labelY + (above ? 14 : -18)} stroke={color} strokeWidth="1.5" />
              <circle cx={pointX} cy={baseline} r="7" fill="var(--card)" stroke={color} strokeWidth="3" />
              <text x={pointX} y={labelY} textAnchor="middle" fill="var(--foreground)" fontSize="11" fontWeight="600">{event.label.length > 18 ? `${event.label.slice(0, 17)}…` : event.label}<title>{event.label}</title></text>
              <text x={pointX} y={labelY + 15} textAnchor="middle" fill="var(--muted-foreground)" fontSize="11">{String(event.date)}</text>
            </g>
          );
        })}
      </svg>
      <ScreenReaderTable><caption>{ariaLabel} data</caption><thead><tr><th scope="col">Event</th><th scope="col">Date</th><th scope="col">Description</th></tr></thead><tbody>{points.map(({ event }) => <tr key={event.id}><th scope="row">{event.label}</th><td>{String(event.date)}</td><td>{event.description ?? ""}</td></tr>)}</tbody></ScreenReaderTable>
    </div>
  );
}

export function MilestoneChart(props: TimelineChartProps) {
  const points = validEvents(props.events);
  if (!points.length) return <ChartEmpty label="No milestones" />;
  const min = points[0].date;
  const max = points[points.length - 1].date;
  const span = Math.max(max - min, 1);
  const x = (value: number) => 58 + ((value - min) / span) * (WIDTH - 116);
  const baseline = HEIGHT - 76;
  return (
    <div className="h-full w-full overflow-x-auto" tabIndex={0} aria-label="Scrollable milestone timeline">
      <svg viewBox={`0 0 ${WIDTH} ${HEIGHT}`} className="h-full min-w-[40rem] w-full" role="group" aria-label={props.ariaLabel ?? "Milestone chart"}>
        <title>{props.ariaLabel ?? "Milestone chart"}</title>
        <line x1="48" x2={WIDTH - 48} y1={baseline} y2={baseline} stroke="var(--chart-axis)" strokeWidth="2" />
        {points.map(({ event, date }, index) => {
          const pointX = x(date);
          const color = taskStatusColor({ id: event.id, name: event.label, start: event.date, end: event.date, status: event.status }, index);
          const stemTop = 72 + (index % 3) * 46;
          return (
            <g key={event.id} tabIndex={0} aria-label={`${event.label}, ${String(event.date)}`} className="ce-svg-mark">
              <line x1={pointX} x2={pointX} y1={stemTop + 18} y2={baseline - 10} stroke={color} strokeDasharray="3 3" />
              <rect x={pointX - 8} y={baseline - 8} width="16" height="16" transform={`rotate(45 ${pointX} ${baseline})`} fill={color} />
              <text x={pointX} y={stemTop} textAnchor="middle" fill="var(--foreground)" fontSize="11" fontWeight="600">{event.label.length > 16 ? `${event.label.slice(0, 15)}…` : event.label}<title>{event.label}</title></text>
              <text x={pointX} y={stemTop + 15} textAnchor="middle" fill="var(--muted-foreground)" fontSize="11">{String(event.date)}</text>
            </g>
          );
        })}
      </svg>
      <ScreenReaderTable><caption>{props.ariaLabel ?? "Milestone chart"} data</caption><thead><tr><th scope="col">Milestone</th><th scope="col">Date</th><th scope="col">Description</th></tr></thead><tbody>{points.map(({ event }) => <tr key={event.id}><th scope="row">{event.label}</th><td>{String(event.date)}</td><td>{event.description ?? ""}</td></tr>)}</tbody></ScreenReaderTable>
    </div>
  );
}

export function ProjectRoadmap(props: ProjectChartProps) {
  const grouped = [...props.data]
    .sort((a, b) => String(a.group ?? "Roadmap").localeCompare(String(b.group ?? "Roadmap")))
    .map((task, index) => ({ ...task, lane: index }));
  return <ProjectBars {...props} data={grouped} showDependencies={false} showProgress ariaLabel={props.ariaLabel ?? "Project roadmap grouped into delivery lanes"} />;
}
