"use client";

import * as React from "react";
import { CHART_COLORS } from "@/lib/chart-colors";
import { useSeriesHover } from "@/lib/chart-motion";
import { formatCompact } from "@/lib/utils";
import { ChartEmpty } from "./chart-frame";

export type FunnelDatum = Record<string, string | number | null | undefined>;

export type FunnelChartProps = {
  data: FunnelDatum[];
  nameKey?: string;
  valueKey?: string;
  variant?: "funnel" | "pyramid";
  valueFormatter?: (value: number) => string;
  ariaLabel?: string;
};

const WIDTH = 680;
const HEIGHT = 340;

function validStages(data: FunnelDatum[], nameKey: string, valueKey: string) {
  return data.flatMap((row, index) => {
    const value = Number(row[valueKey]);
    if (!Number.isFinite(value) || value < 0) return [];
    return [{ label: String(row[nameKey] ?? `Stage ${index + 1}`), value }];
  });
}

export function FunnelChart({
  data,
  nameKey = "name",
  valueKey = "value",
  variant = "funnel",
  valueFormatter = formatCompact,
  ariaLabel,
}: FunnelChartProps) {
  const hover = useSeriesHover();
  const source = React.useMemo(
    () => validStages(data, nameKey, valueKey),
    [data, nameKey, valueKey],
  );
  const stages = variant === "pyramid" ? [...source].reverse() : source;
  const max = Math.max(...stages.map((stage) => stage.value), 0);

  if (!stages.length || max <= 0) return <ChartEmpty label="No valid funnel stages" />;

  const plotLeft = 170;
  const plotRight = 640;
  const center = (plotLeft + plotRight) / 2;
  const plotWidth = plotRight - plotLeft;
  const gap = 5;
  const stageHeight = Math.min(58, (HEIGHT - 28 - gap * (stages.length - 1)) / stages.length);
  const plotTop = (HEIGHT - (stageHeight * stages.length + gap * (stages.length - 1))) / 2;
  const minimumWidth = 24;
  const widthFor = (value: number) => minimumWidth + (value / max) * (plotWidth - minimumWidth);
  const label = ariaLabel ?? `${variant === "pyramid" ? "Pyramid" : "Funnel"} chart with ${stages.length} stages`;

  return (
    <div className="h-full w-full overflow-x-auto">
      <svg
        viewBox={`0 0 ${WIDTH} ${HEIGHT}`}
        className="h-full min-w-[34rem] w-full"
        role="img"
        aria-label={label}
      >
        <title>{label}</title>
        <desc>Connected tapered stages are sized by value. Focus a stage to isolate it.</desc>
        {stages.map((stage, index) => {
          const y = plotTop + index * (stageHeight + gap);
          const topWidth = widthFor(stage.value);
          const following = stages[index + 1];
          const bottomWidth = following
            ? widthFor(following.value)
            : variant === "funnel"
              ? Math.max(minimumWidth, topWidth * 0.62)
              : topWidth;
          const path = [
            `M ${center - topWidth / 2} ${y}`,
            `L ${center + topWidth / 2} ${y}`,
            `L ${center + bottomWidth / 2} ${y + stageHeight}`,
            `L ${center - bottomWidth / 2} ${y + stageHeight}`,
            "Z",
          ].join(" ");
          const color = CHART_COLORS[index % CHART_COLORS.length];
          const opacity = hover.opacityFor(stage.label);
          const conversion = index === 0 || stages[0].value === 0
            ? 1
            : stage.value / stages[0].value;
          return (
            <g
              key={`${stage.label}-${index}`}
              tabIndex={0}
              role="group"
              aria-label={`${stage.label}: ${valueFormatter(stage.value)}, ${Math.round(conversion * 100)} percent of first stage`}
              {...hover.bind(stage.label)}
              style={{ opacity, transition: "opacity 160ms ease-out" }}
            >
              <path d={path} fill={color} />
              <text
                x="154"
                y={y + stageHeight / 2 + 4}
                textAnchor="end"
                fill="var(--muted-foreground)"
                fontSize="12"
              >
                {stage.label.length > 20 ? `${stage.label.slice(0, 19)}…` : stage.label}
                <title>{stage.label}</title>
              </text>
              <g transform={`translate(${center - 38} ${y + stageHeight / 2 - 12})`}>
                <rect
                  width="76"
                  height="24"
                  rx="12"
                  fill="var(--card)"
                  fillOpacity="0.92"
                  stroke="var(--border)"
                />
                <text
                  x="38"
                  y="16"
                  textAnchor="middle"
                  fill="var(--foreground)"
                  fontSize="11"
                  fontWeight="600"
                >
                  {valueFormatter(stage.value)}
                </text>
              </g>
            </g>
          );
        })}
      </svg>
    </div>
  );
}
